def parse_bool(text):
    if not isinstance(text, str):
        raise TypeError("Input must be a string")
    text = text.strip().lower()
    if text in ('true', 'yes', '1'):
        return True
    elif text in ('false', 'no', '0'):
        return False
    else:
        raise ValueError("Invalid boolean string")
